package store

import (
	"errors"
	"fmt"

	"go.mongodb.org/mongo-driver/v2/bson"

	"github.com/tktaofik/capacity-takehome/api/internal/capacity"
)

var (
	ErrUserNotFound     = errors.New("user not found")
	ErrContactNotFound  = errors.New("contact not found")
	ErrRequestNotFound  = errors.New("request not found")
	ErrRequestNotPending = errors.New("request is not pending")
	ErrNotRecipient     = errors.New("only the recipient can respond to this request")
	ErrSelfRequest      = errors.New("cannot send a request to yourself")
	ErrAlreadyConnected = errors.New("already connected with this user")
)

// AcceptCapacityError records which side of an accept failed capacity.
type AcceptCapacityError struct {
	UserID bson.ObjectID
	Err    error
}

func (e *AcceptCapacityError) Error() string {
	return fmt.Sprintf("accept capacity for %s: %v", e.UserID.Hex(), e.Err)
}

func (e *AcceptCapacityError) Unwrap() error { return e.Err }

func IsCapacityError(err error) bool {
	return errors.Is(err, capacity.ErrBudgetFull) || errors.Is(err, capacity.ErrTierFull)
}

package store

import (
	"context"
	"errors"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"

	"github.com/tktaofik/capacity-takehome/api/internal/capacity"
)

// userSeats mirrors active contact counts for atomic capacity enforcement.
type userSeats struct {
	ID    bson.ObjectID `bson:"_id"`
	Pink  int           `bson:"pink"`
	Blue  int           `bson:"blue"`
	Green int           `bson:"green"`
}

func tierField(t capacity.Tier) string {
	switch t {
	case capacity.Pink:
		return "pink"
	case capacity.Blue:
		return "blue"
	case capacity.Green:
		return "green"
	default:
		return "pink"
	}
}

func tierExprField(t capacity.Tier) string {
	return "$" + tierField(t)
}

func (s *Store) ensureUserSeats(ctx context.Context, userID bson.ObjectID) error {
	_, err := s.UserSeats.UpdateOne(ctx,
		bson.M{"_id": userID},
		bson.M{"$setOnInsert": bson.M{"pink": 0, "blue": 0, "green": 0}},
		options.UpdateOne().SetUpsert(true),
	)
	return err
}

func (s *Store) seatCounts(ctx context.Context, userID bson.ObjectID) (capacity.Counts, error) {
	var doc userSeats
	err := s.UserSeats.FindOne(ctx, bson.M{"_id": userID}).Decode(&doc)
	if errors.Is(err, mongo.ErrNoDocuments) {
		return capacity.Counts{}, nil
	}
	if err != nil {
		return nil, err
	}
	return capacity.Counts{
		capacity.Pink:  doc.Pink,
		capacity.Blue:  doc.Blue,
		capacity.Green: doc.Green,
	}, nil
}

func addSeatFilter(userID bson.ObjectID, tier capacity.Tier, caps capacity.Caps) bson.M {
	return bson.M{
		"_id": userID,
		"$expr": bson.M{
			"$and": bson.A{
				bson.M{"$lt": bson.A{
					bson.M{"$add": bson.A{
						bson.M{"$ifNull": bson.A{"$pink", 0}},
						bson.M{"$ifNull": bson.A{"$blue", 0}},
						bson.M{"$ifNull": bson.A{"$green", 0}},
					}},
					caps.Budget,
				}},
				bson.M{"$lt": bson.A{
					bson.M{"$ifNull": bson.A{tierExprField(tier), 0}},
					caps.PerTier[tier],
				}},
			},
		},
	}
}

func moveSeatFilter(userID bson.ObjectID, to capacity.Tier, caps capacity.Caps) bson.M {
	return bson.M{
		"_id": userID,
		"$expr": bson.M{
			"$lt": bson.A{
				bson.M{"$ifNull": bson.A{tierExprField(to), 0}},
				caps.PerTier[to],
			},
		},
	}
}

func (s *Store) tryReserveSeat(ctx context.Context, userID bson.ObjectID, tier capacity.Tier, caps capacity.Caps) error {
	if err := s.ensureUserSeats(ctx, userID); err != nil {
		return err
	}
	err := s.UserSeats.FindOneAndUpdate(ctx,
		addSeatFilter(userID, tier, caps),
		bson.M{"$inc": bson.M{tierField(tier): 1}},
	).Err()
	if err == nil {
		return nil
	}
	if !errors.Is(err, mongo.ErrNoDocuments) {
		return err
	}
	counts, err := s.seatCounts(ctx, userID)
	if err != nil {
		return err
	}
	return capacity.CanAdd(caps, counts, tier)
}

func (s *Store) tryMoveSeat(ctx context.Context, userID bson.ObjectID, from, to capacity.Tier, caps capacity.Caps) error {
	if from == to {
		return nil
	}
	if err := s.ensureUserSeats(ctx, userID); err != nil {
		return err
	}
	err := s.UserSeats.FindOneAndUpdate(ctx,
		moveSeatFilter(userID, to, caps),
		bson.M{"$inc": bson.M{
			tierField(from): -1,
			tierField(to):   1,
		}},
	).Err()
	if err == nil {
		return nil
	}
	if !errors.Is(err, mongo.ErrNoDocuments) {
		return err
	}
	counts, err := s.seatCounts(ctx, userID)
	if err != nil {
		return err
	}
	return capacity.CanMove(caps, counts, from, to)
}

func (s *Store) releaseSeat(ctx context.Context, userID bson.ObjectID, tier capacity.Tier) error {
	if err := s.ensureUserSeats(ctx, userID); err != nil {
		return err
	}
	_, err := s.UserSeats.UpdateOne(ctx,
		bson.M{"_id": userID},
		bson.M{"$inc": bson.M{tierField(tier): -1}},
	)
	return err
}

package store

import (
	"context"
	"errors"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"

	"github.com/tktaofik/capacity-takehome/api/internal/capacity"
)

func (s *Store) SendRequest(ctx context.Context, caps capacity.Caps, fromID, toID bson.ObjectID, tier capacity.Tier) (*Request, error) {
	if fromID == toID {
		return nil, ErrSelfRequest
	}
	if err := s.Users.FindOne(ctx, bson.M{"_id": toID}).Err(); err != nil {
		if errors.Is(err, mongo.ErrNoDocuments) {
			return nil, ErrUserNotFound
		}
		return nil, err
	}
	if err := s.Contacts.FindOne(ctx, bson.M{"ownerId": fromID, "otherId": toID}).Err(); err == nil {
		return nil, ErrAlreadyConnected
	} else if !errors.Is(err, mongo.ErrNoDocuments) {
		return nil, err
	}

	counts, err := s.CountsFor(ctx, fromID)
	if err != nil {
		return nil, err
	}
	if err := capacity.CanSend(caps, counts); err != nil {
		return nil, err
	}

	now := time.Now()
	req := Request{
		FromID:    fromID,
		ToID:      toID,
		Tier:      tier,
		Status:    RequestPending,
		CreatedAt: now,
	}
	res, err := s.Requests.InsertOne(ctx, req)
	if err != nil {
		return nil, err
	}
	req.ID = res.InsertedID.(bson.ObjectID)
	return &req, nil
}

func (s *Store) AcceptRequest(ctx context.Context, caps capacity.Caps, recipientID, requestID bson.ObjectID) (*Contact, error) {
	var req Request
	if err := s.Requests.FindOne(ctx, bson.M{"_id": requestID}).Decode(&req); err != nil {
		if errors.Is(err, mongo.ErrNoDocuments) {
			return nil, ErrRequestNotFound
		}
		return nil, err
	}
	if req.ToID != recipientID {
		return nil, ErrNotRecipient
	}
	if req.Status != RequestPending {
		return nil, ErrRequestNotPending
	}

	session, err := s.Client.StartSession()
	if err != nil {
		return nil, err
	}
	defer session.EndSession(ctx)

	result, err := session.WithTransaction(ctx, func(ctx context.Context) (any, error) {
		if err := s.tryReserveSeat(ctx, req.FromID, req.Tier, caps); err != nil {
			return nil, &AcceptCapacityError{UserID: req.FromID, Err: err}
		}
		if err := s.tryReserveSeat(ctx, req.ToID, req.Tier, caps); err != nil {
			return nil, &AcceptCapacityError{UserID: req.ToID, Err: err}
		}

		now := time.Now()
		fromContact := Contact{
			OwnerID:   req.FromID,
			OtherID:   req.ToID,
			Tier:      req.Tier,
			CreatedAt: now,
		}
		toContact := Contact{
			OwnerID:   req.ToID,
			OtherID:   req.FromID,
			Tier:      req.Tier,
			CreatedAt: now,
		}
		if _, err := s.Contacts.InsertOne(ctx, fromContact); err != nil {
			return nil, err
		}
		res, err := s.Contacts.InsertOne(ctx, toContact)
		if err != nil {
			return nil, err
		}
		toContact.ID = res.InsertedID.(bson.ObjectID)

		update := s.Requests.FindOneAndUpdate(ctx,
			bson.M{"_id": req.ID, "status": RequestPending},
			bson.M{"$set": bson.M{"status": RequestAccepted}},
		)
		if update.Err() != nil {
			if errors.Is(update.Err(), mongo.ErrNoDocuments) {
				return nil, ErrRequestNotPending
			}
			return nil, update.Err()
		}

		return &toContact, nil
	})
	if err != nil {
		return nil, err
	}
	contact, ok := result.(*Contact)
	if !ok {
		return nil, fmt.Errorf("accept request: unexpected result type %T", result)
	}
	return contact, nil
}

func (s *Store) DeclineRequest(ctx context.Context, recipientID, requestID bson.ObjectID) (*Request, error) {
	res := s.Requests.FindOneAndUpdate(ctx,
		bson.M{"_id": requestID, "toId": recipientID, "status": RequestPending},
		bson.M{"$set": bson.M{"status": RequestDeclined}},
	)
	if res.Err() != nil {
		if errors.Is(res.Err(), mongo.ErrNoDocuments) {
			var req Request
			err := s.Requests.FindOne(ctx, bson.M{"_id": requestID}).Decode(&req)
			if errors.Is(err, mongo.ErrNoDocuments) {
				return nil, ErrRequestNotFound
			}
			if err != nil {
				return nil, err
			}
			if req.ToID != recipientID {
				return nil, ErrNotRecipient
			}
			return nil, ErrRequestNotPending
		}
		return nil, res.Err()
	}
	var req Request
	if err := res.Decode(&req); err != nil {
		return nil, err
	}
	return &req, nil
}

func (s *Store) MoveContact(ctx context.Context, caps capacity.Caps, ownerID, contactID bson.ObjectID, to capacity.Tier) (*Contact, error) {
	var contact Contact
	if err := s.Contacts.FindOne(ctx, bson.M{"_id": contactID, "ownerId": ownerID}).Decode(&contact); err != nil {
		if errors.Is(err, mongo.ErrNoDocuments) {
			return nil, ErrContactNotFound
		}
		return nil, err
	}
	if contact.Tier == to {
		return &contact, nil
	}

	session, err := s.Client.StartSession()
	if err != nil {
		return nil, err
	}
	defer session.EndSession(ctx)

	result, err := session.WithTransaction(ctx, func(ctx context.Context) (any, error) {
		if err := s.tryMoveSeat(ctx, ownerID, contact.Tier, to, caps); err != nil {
			return nil, err
		}
		if err := s.tryMoveSeat(ctx, contact.OtherID, contact.Tier, to, caps); err != nil {
			return nil, err
		}

		_, err := s.Contacts.UpdateOne(ctx,
			bson.M{"ownerId": ownerID, "otherId": contact.OtherID},
			bson.M{"$set": bson.M{"tier": to}},
		)
		if err != nil {
			return nil, err
		}
		_, err = s.Contacts.UpdateOne(ctx,
			bson.M{"ownerId": contact.OtherID, "otherId": ownerID},
			bson.M{"$set": bson.M{"tier": to}},
		)
		if err != nil {
			return nil, err
		}

		contact.Tier = to
		return &contact, nil
	})
	if err != nil {
		return nil, err
	}
	moved, ok := result.(*Contact)
	if !ok {
		return nil, fmt.Errorf("move contact: unexpected result type %T", result)
	}
	return moved, nil
}

func (s *Store) RemoveContact(ctx context.Context, ownerID, contactID bson.ObjectID) error {
	var contact Contact
	if err := s.Contacts.FindOne(ctx, bson.M{"_id": contactID, "ownerId": ownerID}).Decode(&contact); err != nil {
		if errors.Is(err, mongo.ErrNoDocuments) {
			return ErrContactNotFound
		}
		return err
	}

	session, err := s.Client.StartSession()
	if err != nil {
		return err
	}
	defer session.EndSession(ctx)

	_, err = session.WithTransaction(ctx, func(ctx context.Context) (any, error) {
		if _, err := s.Contacts.DeleteOne(ctx, bson.M{"ownerId": ownerID, "otherId": contact.OtherID}); err != nil {
			return nil, err
		}
		if _, err := s.Contacts.DeleteOne(ctx, bson.M{"ownerId": contact.OtherID, "otherId": ownerID}); err != nil {
			return nil, err
		}
		if err := s.releaseSeat(ctx, ownerID, contact.Tier); err != nil {
			return nil, err
		}
		if err := s.releaseSeat(ctx, contact.OtherID, contact.Tier); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return err
}

package graph

import (
	"context"
	"errors"
	"fmt"

	"github.com/tktaofik/capacity-takehome/api/graph/model"
	"github.com/tktaofik/capacity-takehome/api/internal/capacity"
	"github.com/tktaofik/capacity-takehome/api/internal/store"
	"go.mongodb.org/mongo-driver/v2/bson"
)

func toCapacityTier(t model.Tier) capacity.Tier {
	return capacity.Tier(t)
}

func toModelTier(t capacity.Tier) model.Tier {
	return model.Tier(t)
}

func toModelRequestStatus(s store.RequestStatus) model.RequestStatus {
	return model.RequestStatus(s)
}

func (r *Resolver) userByID(ctx context.Context, id bson.ObjectID) (*model.User, error) {
	var u store.User
	if err := r.Store.Users.FindOne(ctx, bson.M{"_id": id}).Decode(&u); err != nil {
		return nil, fmt.Errorf("user %s: %w", id.Hex(), err)
	}
	return &model.User{ID: u.ID.Hex(), Name: u.Name}, nil
}

func (r *Resolver) contactToModel(ctx context.Context, c *store.Contact) (*model.Contact, error) {
	user, err := r.userByID(ctx, c.OtherID)
	if err != nil {
		return nil, err
	}
	return &model.Contact{
		ID:        c.ID.Hex(),
		User:      user,
		Tier:      toModelTier(c.Tier),
		CreatedAt: c.CreatedAt,
	}, nil
}

func (r *Resolver) requestToModel(ctx context.Context, req *store.Request) (*model.Request, error) {
	from, err := r.userByID(ctx, req.FromID)
	if err != nil {
		return nil, err
	}
	to, err := r.userByID(ctx, req.ToID)
	if err != nil {
		return nil, err
	}
	return &model.Request{
		ID:        req.ID.Hex(),
		From:      from,
		To:        to,
		Tier:      toModelTier(req.Tier),
		Status:    toModelRequestStatus(req.Status),
		CreatedAt: req.CreatedAt,
	}, nil
}

func mapCapacityError(err error, callerID bson.ObjectID, subjectUserID bson.ObjectID) error {
	var acceptErr *store.AcceptCapacityError
	if errors.As(err, &acceptErr) {
		subject := "Their"
		if acceptErr.UserID == callerID {
			subject = "Your"
		}
		return errors.New(capacityMessage(acceptErr.Err, subject))
	}
	if errors.Is(err, capacity.ErrBudgetFull) {
		return errors.New(capacityMessage(err, "Your"))
	}
	if errors.Is(err, capacity.ErrTierFull) {
		return errors.New(capacityMessage(err, "Your"))
	}
	return err
}

func capacityMessage(err error, subject string) string {
	switch {
	case errors.Is(err, capacity.ErrBudgetFull):
		return fmt.Sprintf("%s contact list is full.", subject)
	case errors.Is(err, capacity.ErrTierFull):
		return fmt.Sprintf("%s tier is full.", subject)
	default:
		return err.Error()
	}
}

func parseObjectID(id string) (bson.ObjectID, error) {
	return bson.ObjectIDFromHex(id)
}

