package store_test

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"

	"github.com/tktaofik/capacity-takehome/api/internal/capacity"
	"github.com/tktaofik/capacity-takehome/api/internal/config"
	"github.com/tktaofik/capacity-takehome/api/internal/store"
)

func testCaps() capacity.Caps {
	return capacity.Caps{
		Budget: 8,
		PerTier: map[capacity.Tier]int{
			capacity.Pink:  1,
			capacity.Blue:  3,
			capacity.Green: 5,
		},
	}
}

func connectStore(t *testing.T) *store.Store {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	t.Cleanup(cancel)

	st, err := store.Connect(ctx, config.MongoURI())
	if err != nil {
		t.Skipf("mongo not available: %v", err)
	}
	t.Cleanup(func() {
		_ = st.Client.Disconnect(context.Background())
	})
	return st
}

func resetCollections(t *testing.T, st *store.Store) {
	t.Helper()
	ctx := context.Background()
	if _, err := st.Contacts.DeleteMany(ctx, bson.M{}); err != nil {
		t.Fatal(err)
	}
	if _, err := st.Requests.DeleteMany(ctx, bson.M{}); err != nil {
		t.Fatal(err)
	}
	if _, err := st.UserSeats.DeleteMany(ctx, bson.M{}); err != nil {
		t.Fatal(err)
	}
	if _, err := st.Users.DeleteMany(ctx, bson.M{}); err != nil {
		t.Fatal(err)
	}
}

func insertUser(t *testing.T, st *store.Store, name string) bson.ObjectID {
	t.Helper()
	res, err := st.Users.InsertOne(context.Background(), store.User{Name: name})
	if err != nil {
		t.Fatal(err)
	}
	return res.InsertedID.(bson.ObjectID)
}

func seedContacts(t *testing.T, st *store.Store, ownerID, otherID bson.ObjectID, tier capacity.Tier) {
	t.Helper()
	ctx := context.Background()
	caps := testCaps()
	now := time.Now()
	_, err := st.AcceptRequest(ctx, caps, otherID, mustRequest(t, st, ownerID, otherID, tier).ID)
	if err != nil {
		// AcceptRequest needs pending request from owner to other; create manually for bulk seed
		t.Fatal(err)
	}
	_ = now
}

func mustRequest(t *testing.T, st *store.Store, from, to bson.ObjectID, tier capacity.Tier) *store.Request {
	t.Helper()
	req, err := st.SendRequest(context.Background(), testCaps(), from, to, tier)
	if err != nil {
		t.Fatal(err)
	}
	return req
}

func fillUserGreen(t *testing.T, st *store.Store, userID bson.ObjectID, n int) {
	t.Helper()
	caps := testCaps()
	ctx := context.Background()
	for i := 0; i < n; i++ {
		other := insertUser(t, st, userID.Hex()+"-partner-"+string(rune('a'+i)))
		req, err := st.SendRequest(ctx, caps, other, userID, capacity.Green)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := st.AcceptRequest(ctx, caps, userID, req.ID); err != nil {
			t.Fatal(err)
		}
	}
}

func TestSendRequestDoesNotConsumeCapacity(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()

	from := insertUser(t, st, "sender")
	to := insertUser(t, st, "recipient")

	if _, err := st.SendRequest(context.Background(), caps, from, to, capacity.Blue); err != nil {
		t.Fatalf("SendRequest: %v", err)
	}

	counts, err := st.CountsFor(context.Background(), from)
	if err != nil {
		t.Fatal(err)
	}
	if counts.Total() != 0 {
		t.Fatalf("pending request consumed capacity: total=%d", counts.Total())
	}
}

func TestAcceptCreatesBilateralContacts(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()
	ctx := context.Background()

	from := insertUser(t, st, "from")
	to := insertUser(t, st, "to")

	req, err := st.SendRequest(ctx, caps, from, to, capacity.Pink)
	if err != nil {
		t.Fatal(err)
	}
	contact, err := st.AcceptRequest(ctx, caps, to, req.ID)
	if err != nil {
		t.Fatal(err)
	}
	if contact.OwnerID != to || contact.OtherID != from || contact.Tier != capacity.Pink {
		t.Fatalf("unexpected contact: %+v", contact)
	}

	fromCounts, err := st.CountsFor(ctx, from)
	if err != nil {
		t.Fatal(err)
	}
	toCounts, err := st.CountsFor(ctx, to)
	if err != nil {
		t.Fatal(err)
	}
	if fromCounts.Total() != 1 || toCounts.Total() != 1 {
		t.Fatalf("want 1 contact each, got from=%d to=%d", fromCounts.Total(), toCounts.Total())
	}
}

func TestAcceptValidatesBothUsers(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()
	ctx := context.Background()

	full := insertUser(t, st, "full")
	recipient := insertUser(t, st, "recipient")
	fillUserGreen(t, st, full, 8)

	req, err := st.SendRequest(ctx, caps, full, recipient, capacity.Pink)
	if err != nil {
		t.Fatal(err)
	}

	_, err = st.AcceptRequest(ctx, caps, recipient, req.ID)
	var capErr *store.AcceptCapacityError
	if !errors.As(err, &capErr) {
		t.Fatalf("AcceptRequest = %v, want AcceptCapacityError", err)
	}
	if capErr.UserID != full {
		t.Fatalf("capacity error user = %v, want requester %v", capErr.UserID, full)
	}
	if !errors.Is(capErr.Err, capacity.ErrBudgetFull) {
		t.Fatalf("capacity error = %v, want ErrBudgetFull", capErr.Err)
	}
}

func TestDeclineRequest(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()
	ctx := context.Background()

	from := insertUser(t, st, "from")
	to := insertUser(t, st, "to")

	req, err := st.SendRequest(ctx, caps, from, to, capacity.Blue)
	if err != nil {
		t.Fatal(err)
	}
	declined, err := st.DeclineRequest(ctx, to, req.ID)
	if err != nil {
		t.Fatal(err)
	}
	if declined.Status != store.RequestDeclined {
		t.Fatalf("status = %q, want DECLINED", declined.Status)
	}

	counts, err := st.CountsFor(ctx, from)
	if err != nil {
		t.Fatal(err)
	}
	if counts.Total() != 0 {
		t.Fatalf("decline created contacts: total=%d", counts.Total())
	}
}

func TestMoveDoesNotChangeTotalCapacity(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()
	ctx := context.Background()

	from := insertUser(t, st, "from")
	to := insertUser(t, st, "to")

	req, err := st.SendRequest(ctx, caps, from, to, capacity.Green)
	if err != nil {
		t.Fatal(err)
	}
	contact, err := st.AcceptRequest(ctx, caps, to, req.ID)
	if err != nil {
		t.Fatal(err)
	}

	fillUserGreen(t, st, to, 4) // to now has 5 green total including contact from above? 
	// Wait - fillUserGreen adds 5 contacts to user. Accept added 1 green. Let me redo.

	resetCollections(t, st)
	from = insertUser(t, st, "from")
	to = insertUser(t, st, "to")
	fillUserGreen(t, st, to, 4) // 4 green for to
	req, err = st.SendRequest(ctx, caps, from, to, capacity.Green)
	if err != nil {
		t.Fatal(err)
	}
	contact, err = st.AcceptRequest(ctx, caps, to, req.ID)
	if err != nil {
		t.Fatal(err)
	}
	// to has 5 green now (full budget for green path - 5/8 total)

	before, err := st.CountsFor(ctx, to)
	if err != nil {
		t.Fatal(err)
	}

	moved, err := st.MoveContact(ctx, caps, to, contact.ID, capacity.Blue)
	if err != nil {
		t.Fatal(err)
	}
	if moved.Tier != capacity.Blue {
		t.Fatalf("tier = %q, want BLUE", moved.Tier)
	}

	after, err := st.CountsFor(ctx, to)
	if err != nil {
		t.Fatal(err)
	}
	if after.Total() != before.Total() {
		t.Fatalf("move changed total capacity: before=%d after=%d", before.Total(), after.Total())
	}
	if after[capacity.Green] != before[capacity.Green]-1 || after[capacity.Blue] != before[capacity.Blue]+1 {
		t.Fatalf("move miscounted tiers: before=%v after=%v", before, after)
	}
}

func TestRemoveReleasesCapacity(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()
	ctx := context.Background()

	from := insertUser(t, st, "from")
	to := insertUser(t, st, "to")

	req, err := st.SendRequest(ctx, caps, from, to, capacity.Pink)
	if err != nil {
		t.Fatal(err)
	}
	contact, err := st.AcceptRequest(ctx, caps, to, req.ID)
	if err != nil {
		t.Fatal(err)
	}

	if err := st.RemoveContact(ctx, to, contact.ID); err != nil {
		t.Fatal(err)
	}

	toCounts, err := st.CountsFor(ctx, to)
	if err != nil {
		t.Fatal(err)
	}
	fromCounts, err := st.CountsFor(ctx, from)
	if err != nil {
		t.Fatal(err)
	}
	if toCounts.Total() != 0 || fromCounts.Total() != 0 {
		t.Fatalf("remove did not release capacity: from=%v to=%v", fromCounts, toCounts)
	}
}

// Rule 4 - two accepts landing at the same moment on a user with exactly one
// free seat must not both succeed. Exactly one wins; the other fails cleanly.
func TestConcurrentAcceptsTakeOneSeat(t *testing.T) {
	st := connectStore(t)
	resetCollections(t, st)
	caps := testCaps()
	ctx := context.Background()

	recipient := insertUser(t, st, "recipient")
	fillUserGreen(t, st, recipient, 7)

	senderA := insertUser(t, st, "sender-a")
	senderB := insertUser(t, st, "sender-b")

	reqA, err := st.SendRequest(ctx, caps, senderA, recipient, capacity.Green)
	if err != nil {
		t.Fatal(err)
	}
	reqB, err := st.SendRequest(ctx, caps, senderB, recipient, capacity.Green)
	if err != nil {
		t.Fatal(err)
	}

	var wg sync.WaitGroup
	wg.Add(2)
	results := make(chan error, 2)

	go func() {
		defer wg.Done()
		_, err := st.AcceptRequest(ctx, caps, recipient, reqA.ID)
		results <- err
	}()
	go func() {
		defer wg.Done()
		_, err := st.AcceptRequest(ctx, caps, recipient, reqB.ID)
		results <- err
	}()
	wg.Wait()
	close(results)

	var successes, failures int
	for err := range results {
		if err == nil {
			successes++
			continue
		}
		failures++
		if !errors.Is(err, capacity.ErrBudgetFull) && !errors.As(err, new(*store.AcceptCapacityError)) {
			t.Fatalf("unexpected failure: %v", err)
		}
	}
	if successes != 1 || failures != 1 {
		t.Fatalf("want exactly one success and one failure, got successes=%d failures=%d", successes, failures)
	}

	counts, err := st.CountsFor(ctx, recipient)
	if err != nil {
		t.Fatal(err)
	}
	if counts.Total() != 8 {
		t.Fatalf("recipient total = %d, want 8", counts.Total())
	}
}

