import { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  SafeAreaView,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { StatusBar } from 'expo-status-bar';

import { gql, GraphQLError } from './src/api';

type User = { id: string; name: string };
type Tier = 'PINK' | 'BLUE' | 'GREEN';
type Contact = { id: string; user: User; tier: Tier };
type TierCapacity = { tier: Tier; used: number; cap: number };
type Capacity = { budgetUsed: number; budgetCap: number; tiers: TierCapacity[] };
type Request = { id: string; from: User; to: User; tier: Tier };

const TIERS: Tier[] = ['PINK', 'BLUE', 'GREEN'];

const DASHBOARD_QUERY = `
  query {
    users { id name }
    capacity { budgetUsed budgetCap tiers { tier used cap } }
    contacts { id user { id name } tier }
    incomingRequests { id from { id name } tier }
  }
`;

type DashboardData = {
  users: User[];
  capacity: Capacity;
  contacts: Contact[];
  incomingRequests: Request[];
};

export default function App() {
  const [users, setUsers] = useState<User[]>([]);
  const [capacity, setCapacity] = useState<Capacity | null>(null);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [incoming, setIncoming] = useState<Request[]>([]);
  const [me, setMe] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);

  const [sendTo, setSendTo] = useState<string | null>(null);
  const [sendTier, setSendTier] = useState<Tier>('BLUE');

  const refresh = useCallback(async (userId: string) => {
    const data = await gql<DashboardData>(DASHBOARD_QUERY, {}, userId);
    setUsers(data.users);
    setCapacity(data.capacity);
    setContacts(data.contacts);
    setIncoming(data.incomingRequests);
  }, []);

  const load = useCallback(async () => {
    if (!me) {
      try {
        setError(null);
        const boot = await gql<{ users: User[] }>(`{ users { id name } }`);
        setUsers(boot.users);
        const first = boot.users[0]?.id ?? null;
        setMe(first);
        if (first) await refresh(first);
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
      } finally {
        setLoading(false);
      }
      return;
    }

    try {
      setError(null);
      await refresh(me);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, [me, refresh]);

  useEffect(() => {
    void load();
  }, [load]);

  const switchUser = (userId: string) => {
    setMe(userId);
    setActionError(null);
    setSendTo(null);
    setLoading(true);
  };

  useEffect(() => {
    if (me) {
      setLoading(true);
      refresh(me)
        .catch((e) => setError(e instanceof Error ? e.message : String(e)))
        .finally(() => setLoading(false));
    }
  }, [me, refresh]);

  const runAction = async (fn: () => Promise<void>) => {
    if (!me) return;
    setBusy(true);
    setActionError(null);
    try {
      await fn();
      await refresh(me);
    } catch (e) {
      setActionError(e instanceof GraphQLError ? e.message : e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  };

  const acceptRequest = (requestId: string) =>
    runAction(async () => {
      await gql(`mutation($id: ID!) { acceptRequest(requestId: $id) { id } }`, { id: requestId }, me!);
    });

  const declineRequest = (requestId: string) =>
    runAction(async () => {
      await gql(`mutation($id: ID!) { declineRequest(requestId: $id) { id } }`, { id: requestId }, me!);
    });

  const sendRequest = () => {
    if (!me || !sendTo) return;
    runAction(async () => {
      await gql(
        `mutation($to: ID!, $tier: Tier!) { sendRequest(toUserId: $to, tier: $tier) { id } }`,
        { to: sendTo, tier: sendTier },
        me,
      );
      setSendTo(null);
    });
  };

  const moveContact = (contactId: string, tier: Tier) =>
    runAction(async () => {
      await gql(
        `mutation($id: ID!, $tier: Tier!) { moveContact(contactId: $id, tier: $tier) { id } }`,
        { id: contactId, tier },
        me!,
      );
    });

  const removeContact = (contactId: string) =>
    runAction(async () => {
      await gql(`mutation($id: ID!) { removeContact(contactId: $id) }`, { id: contactId }, me!);
    });

  const otherUsers = users.filter((u) => u.id !== me);
  const contactsByTier = (tier: Tier) => contacts.filter((c) => c.tier === tier);
  const tierCap = (tier: Tier) => capacity?.tiers.find((t) => t.tier === tier);

  return (
    <SafeAreaView style={styles.screen}>
      <StatusBar style="auto" />
      <ScrollView contentContainerStyle={styles.body}>
        <Text style={styles.title}>Acting as</Text>

        {loading && <ActivityIndicator />}

        {error && (
          <View style={styles.error}>
            <Text style={styles.errorText}>{error}</Text>
            <Text style={styles.hint}>Is the API up? `make up` then `make api`.</Text>
            <Pressable onPress={load} style={styles.retry}>
              <Text style={styles.retryText}>Retry</Text>
            </Pressable>
          </View>
        )}

        {actionError && (
          <View style={styles.error}>
            <Text style={styles.errorText}>{actionError}</Text>
            <Pressable onPress={() => setActionError(null)} style={styles.retry}>
              <Text style={styles.retryText}>Dismiss</Text>
            </Pressable>
          </View>
        )}

        <View style={styles.list}>
          {users.map((u) => {
            const active = u.id === me;
            return (
              <Pressable
                key={u.id}
                onPress={() => switchUser(u.id)}
                style={[styles.row, active && styles.rowActive]}
              >
                <Text style={[styles.name, active && styles.nameActive]}>{u.name}</Text>
                {active && <Text style={styles.check}>current</Text>}
              </Pressable>
            );
          })}
        </View>

        {capacity && (
          <View style={styles.section}>
            <Text style={styles.title}>Capacity</Text>
            <Text style={styles.budget}>
              Budget: {capacity.budgetUsed} / {capacity.budgetCap}
            </Text>
            {capacity.tiers.map((t) => (
              <Text key={t.tier} style={styles.capLine}>
                {t.tier}: {t.used} / {t.cap}
              </Text>
            ))}
          </View>
        )}

        {TIERS.map((tier) => {
          const cap = tierCap(tier);
          const tierContacts = contactsByTier(tier);
          return (
            <View key={tier} style={styles.section}>
              <Text style={styles.title}>
                {tier} ({cap?.used ?? 0}/{cap?.cap ?? 0})
              </Text>
              {tierContacts.length === 0 && <Text style={styles.empty}>No contacts</Text>}
              {tierContacts.map((c) => (
                <View key={c.id} style={styles.row}>
                  <Text style={styles.name}>{c.user.name}</Text>
                  <View style={styles.actions}>
                    {TIERS.filter((t) => t !== c.tier).map((t) => (
                      <Pressable
                        key={t}
                        disabled={busy}
                        onPress={() => moveContact(c.id, t)}
                        style={styles.actionBtn}
                      >
                        <Text style={styles.actionText}>→{t[0]}</Text>
                      </Pressable>
                    ))}
                    <Pressable disabled={busy} onPress={() => removeContact(c.id)} style={styles.removeBtn}>
                      <Text style={styles.actionText}>✕</Text>
                    </Pressable>
                  </View>
                </View>
              ))}
            </View>
          );
        })}

        <View style={styles.section}>
          <Text style={styles.title}>Incoming requests</Text>
          {incoming.length === 0 && <Text style={styles.empty}>No pending requests</Text>}
          {incoming.map((req) => (
            <View key={req.id} style={styles.row}>
              <Text style={styles.name}>
                {req.from.name} → {req.tier}
              </Text>
              <View style={styles.actions}>
                <Pressable disabled={busy} onPress={() => acceptRequest(req.id)} style={styles.acceptBtn}>
                  <Text style={styles.actionText}>Accept</Text>
                </Pressable>
                <Pressable disabled={busy} onPress={() => declineRequest(req.id)} style={styles.declineBtn}>
                  <Text style={styles.actionText}>Decline</Text>
                </Pressable>
              </View>
            </View>
          ))}
        </View>

        <View style={styles.section}>
          <Text style={styles.title}>Send request</Text>
          <Text style={styles.subtitle}>To</Text>
          <View style={styles.list}>
            {otherUsers.map((u) => (
              <Pressable
                key={u.id}
                onPress={() => setSendTo(u.id)}
                style={[styles.row, sendTo === u.id && styles.rowActive]}
              >
                <Text style={[styles.name, sendTo === u.id && styles.nameActive]}>{u.name}</Text>
              </Pressable>
            ))}
          </View>
          <Text style={styles.subtitle}>Tier</Text>
          <View style={styles.actions}>
            {TIERS.map((t) => (
              <Pressable
                key={t}
                onPress={() => setSendTier(t)}
                style={[styles.tierChip, sendTier === t && styles.rowActive]}
              >
                <Text style={[styles.name, sendTier === t && styles.nameActive]}>{t}</Text>
              </Pressable>
            ))}
          </View>
          <Pressable
            disabled={busy || !sendTo}
            onPress={sendRequest}
            style={[styles.sendBtn, (!sendTo || busy) && styles.sendBtnDisabled]}
          >
            <Text style={styles.sendText}>Send request</Text>
          </Pressable>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: '#fff' },
  body: { padding: 20, gap: 16, paddingBottom: 40 },
